// 课标词汇补全：⚠️ 本文件**不再**直接调用 applyKebiaoTo。
//
// WAIYANSHE_CURRICULUM 是两条教材线的共同基线：
//  - waiyanshe3（三年级起点）= 本数组 grade>=3 部分，**本次重建对象 ⇒ 不补课标**；
//  - waiyanshe（一年级起点）  = 非重建对象，需在派生时**对副本**追加课标。
// 若在共享基线上直接追加，课标单元会同时污染重建的三起线 ⇒ 改由
// curriculum.ts 的 withKebiao() 只对一起线副本执行（见该文件注释）。
